import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"电脑（远程 Runtime）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/computers.md","filePath":"zh/guides/computers.md","lastUpdated":1785920317000}'),o={name:"zh/guides/computers.md"};function i(l,e,n,h,d,c){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="电脑-远程-runtime" tabindex="-1">电脑（远程 Runtime） <a class="header-anchor" href="#电脑-远程-runtime" aria-label="Permalink to &quot;电脑（远程 Runtime）&quot;">​</a></h1><p>可以把你自己的电脑接进 Memoh 部署，让机器人在上面干活：读写文件、跑命令。Web UI 里这叫<strong>电脑</strong>（Computers）；机器人这边以<strong>使用位置</strong>（Work locations）的形式在它们之间选。</p><p>Agent 本体不挪窝。模型调用、聊天、会话、记忆全在 Memoh server 上——接进来的电脑只提供文件系统和命令执行，在 agent 眼里就是又一个 workspace。</p><p>连接方向是电脑<strong>主动连 server</strong> 的 WebSocket。电脑不需要公网 IP、不需要开端口，在 NAT 后面也行。</p><div class="danger custom-block"><p class="custom-block-title">想清楚你在共享什么</p><p>接入的电脑暴露的是跑 runtime 的那个系统用户能访问的文件，命令也<strong>以该用户身份</strong>执行。没有目录沙箱：那个用户碰得到的，有权限的机器人就碰得到。只有你明确添加了这台电脑的机器人才能用它，写/执行默认也要审批——但心态上要按&quot;给了个 shell&quot;来对待。</p></div><hr><h2 id="接入一台电脑" tabindex="-1">接入一台电脑 <a class="header-anchor" href="#接入一台电脑" aria-label="Permalink to &quot;接入一台电脑&quot;">​</a></h2><h3 id="命令行方式" tabindex="-1">命令行方式 <a class="header-anchor" href="#命令行方式" aria-label="Permalink to &quot;命令行方式&quot;">​</a></h3><ol><li>打开 Web UI 设置里的 <strong>Computers</strong> 页。</li><li>创建一个 runtime key（形如 <code>mrk_...</code>；任何登录用户都能建，电脑归创建 key 的用户所有）。</li><li>在要接入的电脑上跑页面生成的命令（Node.js 20+）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @memohai/runtime</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://your-memoh-server/api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mrk_xxxx</span></span></code></pre></div><p>连接强制 <code>wss://</code>（TLS）；纯 <code>http</code> 只允许 localhost 且要加 <code>--insecure-localhost</code>（适用时 UI 会自动带上）。断线自动指数退避重连。</p><p>server 地址和 key 也可以用环境变量 <code>MEMOH_RUNTIME_SERVER</code> / <code>MEMOH_RUNTIME_KEY</code> 给。</p><h3 id="桌面版方式" tabindex="-1">桌面版方式 <a class="header-anchor" href="#桌面版方式" aria-label="Permalink to &quot;桌面版方式&quot;">​</a></h3><p>Memoh Desktop 内置了这个能力：打开<strong>这台电脑</strong>开关、起个名字，App 进程内直接连——不用另开终端。key 用系统钥匙串加密存储，重启自动恢复连接，并且绑定配置时的 server（桌面版换连别的 server 时它会进错误状态，不会悄悄挂到新 server 上）。</p><h3 id="key-管理" tabindex="-1">key 管理 <a class="header-anchor" href="#key-管理" aria-label="Permalink to &quot;key 管理&quot;">​</a></h3><ul><li><strong>吊销</strong> key 会立刻断开对应电脑。</li><li>key 对所有者保持可见，方便日后再复制连接命令——也就是说 server 侧是可读存储的，server 数据库要按敏感数据保护。</li></ul><hr><h2 id="机器人的使用位置" tabindex="-1">机器人的使用位置 <a class="header-anchor" href="#机器人的使用位置" aria-label="Permalink to &quot;机器人的使用位置&quot;">​</a></h2><p>每个机器人有一组<strong>使用位置</strong>（Work locations）：</p><ul><li><strong>服务器工作区</strong>——机器人在 server 上的常规容器 workspace。恒定存在，删不掉。</li><li>你加给这个机器人的若干<strong>电脑</strong>。</li></ul><p>其中恰好一个是<strong>默认位置</strong>，没特别指定时活都在那干。给机器人加电脑需要 bot 管理权限，且电脑只能挂到<strong>同一个用户</strong>拥有的机器人上。</p><p>位置行会显示状态：在线、离线、或 <strong>Update required</strong>（电脑上的 <code>@memohai/runtime</code> 客户端比 server 要求的旧——重启 <code>npx</code> 会自动拿最新版）。</p><h3 id="按请求选位置" tabindex="-1">按请求选位置 <a class="header-anchor" href="#按请求选位置" aria-label="Permalink to &quot;按请求选位置&quot;">​</a></h3><ul><li>聊天输入框有<strong>电脑选择器</strong>，单条消息的活可以指定到某个位置。</li><li>Agent 每次工具调用也可以指定位置；指定的位置不可用时<strong>明着报错</strong>，绝不静默回落到 server 或别的电脑。</li><li>Agent 可以用 <code>list_execution_locations</code> 工具列出当前机器人的位置。</li></ul><h3 id="按位置的工具审批" tabindex="-1">按位置的工具审批 <a class="header-anchor" href="#按位置的工具审批" aria-label="Permalink to &quot;按位置的工具审批&quot;">​</a></h3><p>每个位置有自己独立的审批策略：<strong>读 / 写 / 执行</strong>各自设 allow / ask / deny。电脑的默认值：读 <strong>allow</strong>、写 <strong>ask</strong>、执行 <strong>ask</strong>——机器人可以随便看，但要改你机器上的文件或跑命令得先问。审批请求钉在发起时的那个位置上。</p><hr><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li><strong>Browser Use / Computer Use 永远在服务器工作区里跑</strong>，不跟随所选位置。</li><li><strong>ACP agent 会话</strong>不支持指定电脑。</li><li>路径：runtime 以系统用户的 home 目录为工作根；工具调用里的 <code>~</code> 和 <code>/data</code> 会映射到 home，兼容容器 workspace 的路径习惯。</li></ul><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/guides/container.html">Workspace</a></li><li><a href="/zh/guides/browser-computer-use.html">Browser / Computer Use</a></li><li><a href="/zh/self-hosted/">自托管总览</a></li></ul>',32)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
